NEW_FILES = {'migrations/migrate_ramp_cut.py': '#!/usr/bin/env python3\n"""\nmigrate_ramp_cut.py  --  nothing stands in a ramp\'s cut (0.273.0)\n==================================================================\nOne-shot, idempotent migration over specs/*.json for the factory\'s roadmap 270.\n\n0.273.0 starts a ramp\'s slab cut where a body clears the slab (`stairwell.ramp_cut_span`), not at its middle, and\nfurnish keeps every piece off the cut (`level_design.ramp_holes`). Furniture placed before stood in the longer cuts.\nMeasured over the library before it ran:\n\n  cbp_town_finale_midbalanced_schemafixed  storey 1: cartons_ra81f68c3_10, desk_r6b7fb888_1,\n                                           chair_set_r6b7fb888_1_1                        -- furnished\n  foundry_heist_vertical                   storey 0: pallets_r72ebbdd3_6, barrel_drum_r72ebbdd3_7 -- furnished\n                                                     forklift_cover, loading_crate_stack_a        -- AUTHORED\n\nA furnished piece moves with a refurnish (the chain every refurnishing migration runs). An authored piece is the\nspec\'s own and is moved here, explicitly, by the least distance that clears the cut and its rail (0.3 m, the hole\nclearance furnish keeps), along the ramp\'s width, inside the room it stood in:\n\n  forklift_cover         x 12.0 -> 10.6  (the cut\'s west edge is 12.3; half its 2.6 m width, 1.3, and 0.3 clear)\n  loading_crate_stack_a  x 17.0 -> 17.6  (the cut\'s east edge is 15.7; half its 3.0 m width, 1.5, and 0.3 clear)\n\n    python migrations/migrate_ramp_cut.py            # write specs/\n    python migrations/migrate_ramp_cut.py --check    # report only; exit 1 if any\n"""\nimport glob\nimport io\nimport json\nimport os\nimport sys\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, ROOT)\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\n\nimport level_design  # noqa: E402\nimport migrate_furnish_recipes  # noqa: E402\nimport migrate_seed_corridor  # noqa: E402\nimport migrate_seed_lines  # noqa: E402\nimport migrate_shelter  # noqa: E402\nimport migrate_wall_crossing  # noqa: E402\n\n#: The authored pieces the longer cuts reach: (spec, volume, axis, from, to), each asserted before it moves.\nAUTHORED_MOVES = (("foundry_heist_vertical", "forklift_cover", "x", 12.0, 10.6),\n                  ("foundry_heist_vertical", "loading_crate_stack_a", "x", 17.0, 17.6))\n\n\ndef in_cuts(d):\n    """``[(story, volume name)]``: every volume standing on a storey whose floor a ramp cuts, inside the cut."""\n    H = float(d.get("story_height", 3.0))\n    out = []\n    for story in sorted({int(r.get("to_story", 0)) for r in d.get("ramps") or []}):\n        holes = level_design.ramp_holes(d, story)\n        if not holes:\n            continue\n        floor = story * H\n        for v in d.get("volumes") or []:\n            vz, vh = float(v.get("z", 0.0)), float(v.get("size_z", 0.0))\n            if not (floor - 0.05 <= vz - vh / 2.0 <= floor + H - 0.1):\n                continue\n            for x0, y0, x1, y1 in holes:\n                if (abs(v["x"] - (x0 + x1) / 2.0) < (x1 - x0) / 2.0 + v.get("size_x", 0.0) / 2.0\n                        and abs(v["y"] - (y0 + y1) / 2.0) < (y1 - y0) / 2.0 + v.get("size_y", 0.0) / 2.0):\n                    out.append((story, v["name"]))\n                    break\n    return out\n\n\ndef migrate(d, name):\n    """Move this spec\'s authored pieces out of its cuts, then refurnish it. Returns what still stands in a cut."""\n    for spec, vol, axis, old, new in AUTHORED_MOVES:\n        if spec != name:\n            continue\n        v = next(x for x in d["volumes"] if x["name"] == vol)\n        if abs(v[axis] - new) < 1e-9:\n            continue\n        assert abs(v[axis] - old) < 1e-9, (name, vol, v[axis], old)\n        v[axis] = new\n    migrate_furnish_recipes.migrate(d)\n    migrate_shelter.migrate(d)\n    migrate_seed_corridor.migrate(d)\n    migrate_seed_lines.migrate(d)\n    migrate_wall_crossing.migrate(d)\n    return in_cuts(d)\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    check = "--check" in argv\n    todo = 0\n    for p in sorted(glob.glob(os.path.join(ROOT, "specs", "*.json"))):\n        name = os.path.basename(p)[:-5]\n        if name.startswith("lf_"):\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        if not isinstance(d, dict) or not d.get("ramps"):\n            continue\n        found = in_cuts(d)\n        if not found:\n            continue\n        todo += 1\n        print("[ramp_cut] %s: %s" % (name, ", ".join("%s (storey %d)" % (n, s) for s, n in found)))\n        if check:\n            continue\n        left = migrate(d, name)\n        assert not left, (name, left)\n        io.open(p, "w", encoding="utf-8", newline="\\n").write(json.dumps(d, indent=1) + "\\n")\n    print("[ramp_cut] %d spec(s) %s" % (todo, "need it" if check else "cleared"))\n    return 1 if check and todo else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_ramp_cut_headroom.py': '"""0.273.0 -- a ramp\'s cut begins where a body clears the slab, and nothing stands in it (the factory\'s roadmap 270).\n\nThe walker, on seed 9205\'s parking garage, 2026-10-26: "i can\'t use this wide ramp to go up or down?". Every library\nramp\'s cut began at its middle, where the gap between the ramp and the slab above was 1.04 to 1.55 m against the\nagent contract\'s 2.0. FAILS ON 0.272.0.\n"""\nimport glob\nimport json\nimport os\nimport sys\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, ROOT)\nsys.path.insert(0, os.path.join(ROOT, "migrations"))\n\nimport agent_contract  # noqa: E402\nimport migrate_ramp_cut as M  # noqa: E402\nimport stairwell  # noqa: E402\n\n\ndef _ramped():\n    for p in sorted(glob.glob(os.path.join(ROOT, "specs", "*.json"))):\n        name = os.path.basename(p)[:-5]\n        if name.startswith("lf_"):\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        if isinstance(d, dict) and d.get("ramps"):\n            yield name, d\n\n\ndef _gap_at(d, r, t):\n    """The gap between the ramp\'s top at `t` along its ascent and the underside of the slab it climbs to."""\n    rise = float(d["story_height"]) * (r["to_story"] - r["from_story"])\n    t_low = stairwell._ramp_ascent(r)[0]\n    return rise - float(d.get("floor_thick", 0.0)) - rise * (t - t_low) / float(r.get("run", 8.0))\n\n\ndef test_every_library_ramp_cut_begins_where_a_body_clears_the_slab():\n    hr = agent_contract.min_headroom()\n    ramps = 0\n    for name, d in _ramped():\n        for r in d["ramps"]:\n            if not r.get("cut_slabs", True) or r["to_story"] <= r["from_story"]:\n                continue\n            ramps += 1\n            start = stairwell.ramp_cut_span(r, d)[0]\n            assert _gap_at(d, r, start) >= hr - 1e-6, (name, round(_gap_at(d, r, start), 3))\n            assert start <= stairwell.ramp_cut_span(r)[0] + 1e-9, name      # never later than the middle\n    assert ramps == 9          # the nine library ramps roadmap 270 measured\n\n\ndef test_the_garage_the_walker_tried_opens_two_thirds_further_down():\n    d = json.load(open(os.path.join(ROOT, "specs", "parking_garage.json"), encoding="utf-8"))\n    r = d["ramps"][0]\n    t_low = stairwell._ramp_ascent(r)[0]\n    assert round(stairwell.ramp_cut_span(r)[0] - t_low, 3) == 5.0                    # where it began\n    assert round(stairwell.ramp_cut_span(r, d)[0] - t_low, 3) == round(10.0 * 0.7 / 3.0, 3)  # 2.333 m up the ramp\n    hole = stairwell.ramp_hole(r, d)\n    assert hole[3 if r["axis"] == "Y" else 2] > stairwell.ramp_hole(r)[3 if r["axis"] == "Y" else 2]\n\n\ndef test_nothing_stands_in_a_ramps_cut_and_furnish_keeps_off_it():\n    assert M.main(["--check"]) == 0, "run: python migrations/migrate_ramp_cut.py"\n    for name, d in _ramped():\n        assert M.in_cuts(d) == [], name\n\n\ndef test_the_authored_pieces_moved_by_the_least_distance():\n    d = json.load(open(os.path.join(ROOT, "specs", "foundry_heist_vertical.json"), encoding="utf-8"))\n    at = {v["name"]: v for v in d["volumes"]}\n    assert at["forklift_cover"]["x"] == 10.6 and at["loading_crate_stack_a"]["x"] == 17.6\n'}
CHANGELOG = '## [0.273.0] - a ramp\'s cut begins where a body clears the slab, and nothing stands in it\n\n**The factory\'s roadmap 270.** The walker, on seed 9205\'s parking garage, 2026-10-26: "i can\'t use this wide ramp to\ngo up or down?". Every library ramp\'s slab cut began at the ramp\'s middle. There the gap between the ramp\'s top and\nthe slab it climbs to was 1.04 to 1.55 m, against the agent contract\'s `min_headroom_m` of 2.0, so a body met the\nslab\'s edge, up or down.\n\n### Changed\n- **`stairwell.ramp_cut_span(rp, spec)`**: the cut begins where that gap falls to `min_headroom_m`, at\n  `t_low + run * (rise - slab - headroom) / rise`, and never later than the middle.\n  - Across the nine library ramps the start moves 0.9 to 2.7 m down each ramp. The parking garages\' cut now starts\n    2.33 m from the foot where it started at 5.00, and every gap where a cut starts is 2.00 m.\n  - `ramp_hole` and every caller (the builder, `slab_openings`, `stair_guards`, the stair walk-off) pass the spec,\n    so the rails, wall voids and holes follow the longer cut.\n  - Without a spec the cut begins at the middle, as before.\n- **Furnish keeps every piece off a ramp\'s cut** (`level_design.ramp_holes`), as it keeps off an authored hole. This\n  applies to piece placement and to the seeded corridor\'s obstacles.\n- **`migrations/migrate_ramp_cut.py`** clears what stood in the longer cuts.\n  - `cbp_town_finale`: cartons, a desk and a chair set, refurnished.\n  - `foundry_heist_vertical`: pallets and a drum refurnished, and two AUTHORED pieces moved by the least distance\n    that clears the cut and its rail: `forklift_cover` x 12.0 -> 10.6 and `loading_crate_stack_a` x 17.0 -> 17.6,\n    both still in the loading dock.\n- `tests/test_ramp_cut.py`\'s two rail tests ask the rails of the cut the builder makes, `ramp_hole(rp, spec)`.\n\n### Tests\n- `tests/test_ramp_cut_headroom.py` (all 4 fail on 0.272.0):\n  - every library ramp\'s cut begins where the gap is at least 2.0 m and no later than its middle;\n  - the walker\'s garage opens 2.33 m up its ramp;\n  - nothing stands in any cut;\n  - the authored pieces moved by the least distance.\n- Layout lint over the garages unchanged: the same warnings before and after.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.272.0', 'Deli Counter 0.273.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
